import cpmpy as cp
import json

# Input data
n = 13  # Number of balls
c = 3  # Number of boxes

# Model definition
model = cp.Model()

# Decision Variables
M = cp.boolvar(shape=(n, c), name="M")  # M[i][j] is True if ball i+1 is in box j+1

# Constraints
# Each ball must be in exactly one box
for i in range(n):
    model += cp.sum(M[i]) == 1

# For each x + y = z, not all three in the same box
for x in range(n):
    for y in range(n):
        z = x + y + 1  # balls are labeled 1..n, so x+1 + y+1 = z+1 => z = x + y + 1
        if z < n:  # z must be <= n (since balls are 1..n)
            for j in range(c):
                model += M[x][j] + M[y][j] + M[z][j] <= 2

# Solve and print
if model.solve():
    # Convert solution to list of box assignments (1..c) for each ball (1..n)
    balls = []
    for i in range(n):
        for j in range(c):
            if M[i][j].value():
                balls.append(j+1)
                break
    solution = {'balls': balls}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
